import pickle

class Versioned:
    def __init__(self, value):
        self.value = value

    def __reduce__(self):
        return (Versioned, (self.value,))  # (可调用对象, 参数元组)


original = Versioned(42)
restored = pickle.loads(pickle.dumps(original))
print(restored.value, restored.value == original.value)
